public static class UimSwapStub
{
    public static void Main() { }

    public static bool Fake(int playerNum, string broName) { return true; }

    public static bool SwapThenRespawn(int playerNum, string broName)
    {
        bool swapped = Swap_Bros_Mod.API.SwapByName(playerNum, broName);
        new GameObject("UimRespawnLater").AddComponent<UimRespawnLater>().Player = playerNum;
        return swapped;
    }

    public static void Unload()
    {
        foreach (var later in Object.FindObjectsOfType<UimRespawnLater>()) Object.Destroy(later.gameObject);
    }
}

public class UimRespawnLater : MonoBehaviour
{
    public int Player;
    private float at;

    void Start() { at = Time.realtimeSinceStartup + 0.2f; }

    void Update()
    {
        if (Time.realtimeSinceStartup < at) return;
        var player = HeroController.players[Player];
        if (player != null) player.SpawnHero(HeroType.Rambro);
        Destroy(gameObject);
    }
}

